using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Web.Script.Serialization;
namespace PZ3D {
 static class FeatureTests {
  public static void Real(string cache){
   DlssInstaller.ValidateCache(cache);string root=Path.Combine(Path.GetTempPath(),"orange-real-components-"+Guid.NewGuid().ToString("N"));string game=Path.Combine(root,"game"),data=Path.Combine(root,"data");Directory.CreateDirectory(game);File.WriteAllText(Path.Combine(game,"ProjectZomboid64.json"),"{\"vmArgs\":[\"-Xmx28672m\"]}");string header=Path.Combine(game,"reshade-shaders","Shaders","ReShade.fxh");Directory.CreateDirectory(Path.GetDirectoryName(header));File.WriteAllText(header,"original header preserved");var d=new DlssInstaller(game,data,true);d.Enable(cache);Check(DlssInstaller.HashFile(Path.Combine(game,"opengl32.dll"))==DlssInstaller.HashFile(Path.Combine(cache,"opengl32.dll")),"real downloaded OpenGL binary copied exactly into isolated fixture");Check(File.Exists(Path.Combine(game,"reshade-shaders","Shaders","include","lumenite_Compute.fxh")),"real motion provider include dependencies installed");new Engine(game,Path.Combine(root,"user"),data,true).Switch(false,false);Check(!d.Enabled&&!File.Exists(Path.Combine(game,"opengl32.dll")),"closing 3D also removes managed DLSS deployment");Check(File.ReadAllText(header)=="original header preserved","original shader header restored from exact backup");Check(File.ReadAllText(Path.Combine(game,"ProjectZomboid64.json")).Contains("28672m"),"coupled disable preserves game memory setting");Console.WriteLine("REAL COMPONENT FILE TEST PASSED (not an in-game rendering test): "+root);
  }
  static void Check(bool value,string message){if(!value)throw new Exception("FAIL: "+message);Console.WriteLine("PASS: "+message);}
  static object Call(object o,string name,params object[] args){try{return o.GetType().GetMethod(name).Invoke(o,args);}catch(TargetInvocationException e){throw e.InnerException;}}
  static byte[] Pe(){byte[] b=new byte[512];b[0]=77;b[1]=90;b[60]=128;b[128]=80;b[129]=69;b[132]=100;b[133]=134;return b;}
  public static void Run(){
   Type type=typeof(Engine).Assembly.GetType("PZ3D.DlssInstaller");Check(type!=null,"real reversible DLSS installer is available");
   string root=Path.Combine(Path.GetTempPath(),"orange-dlss-test-"+Guid.NewGuid().ToString("N"));string game=Path.Combine(root,"game"),cache=Path.Combine(root,"cache"),data=Path.Combine(root,"data");Directory.CreateDirectory(game);Directory.CreateDirectory(cache);File.WriteAllText(Path.Combine(game,"ProjectZomboid64.json"),"{\"vmArgs\":[]}");
   object installer=Activator.CreateInstance(type,new object[]{game,data,true});bool refused=false;try{Call(installer,"Enable",cache);}catch{refused=true;}Check(refused&&!File.Exists(Path.Combine(game,"opengl32.dll")),"missing components refuse all game mutation");
   foreach(string file in new[]{"opengl32.dll","dlss5-feed.addon64","renodx-dlss5.addon64","nvngx_dlss.dll","nvngx_dlssnr.dll"})File.WriteAllBytes(Path.Combine(cache,file),Pe());
   Directory.CreateDirectory(Path.Combine(cache,"reshade-shaders","Shaders","include"));Directory.CreateDirectory(Path.Combine(cache,"reshade-shaders","Textures"));foreach(string file in new[]{"DLSS5_Feed.fx","ReShade.fxh","ReShadeUI.fxh","DrawText.fxh","lumenite_Kernel.fx"})File.WriteAllText(Path.Combine(cache,"reshade-shaders","Shaders",file),"fixture shader");File.WriteAllText(Path.Combine(cache,"reshade-shaders","Shaders","include","lumenite_common.fxh"),"fixture include");
   File.WriteAllText(Path.Combine(game,"UserNotes.txt"),"keep me");File.WriteAllText(Path.Combine(game,"ReShade.ini"),"old unrelated config");refused=false;try{Call(installer,"Enable",cache);}catch{refused=true;}Check(refused&&File.ReadAllText(Path.Combine(game,"ReShade.ini"))=="old unrelated config","existing unmanaged ReShade is not overwritten");File.Move(Path.Combine(game,"ReShade.ini"),Path.Combine(game,"OriginalReShade.ini"));
   Call(installer,"Enable",cache);Check(File.Exists(Path.Combine(game,"opengl32.dll"))&&File.ReadAllText(Path.Combine(game,"dlss5-feed.cfg")).Contains("enabled=1"),"enable deploys actual OpenGL loader and enabled feed config");Check(File.ReadAllText(Path.Combine(game,"ReShadePreset.ini")).Contains("Lumenite_Kernel@lumenite_Kernel.fx,DLSS5_Feed@DLSS5_Feed.fx"),"motion provider runs before feed");
   string backup=(string)type.GetProperty("LastBackup").GetValue(installer,null);Check(File.Exists(Path.Combine(backup,"changes.json"))&&File.Exists(Path.Combine(backup,"人工关闭DLSS5.txt")),"DLSS exact file journal and manual restoration persisted");Call(installer,"Enable",cache);Check((bool)type.GetProperty("Enabled").GetValue(installer,null),"repeat enable keeps tracked deployment");
   File.WriteAllText(Path.Combine(game,"dlss5-feed.cfg"),"enabled=0\nuser edit");Call(installer,"Disable");Check(!File.Exists(Path.Combine(game,"opengl32.dll"))&&!File.Exists(Path.Combine(game,"nvngx_dlssnr.dll")),"one-click disable removes owned injection files");Check(File.ReadAllText(Path.Combine(game,"UserNotes.txt"))=="keep me"&&File.ReadAllText(Path.Combine(game,"OriginalReShade.ini"))=="old unrelated config","disable preserves unrelated user files");Check(Directory.EnumerateFiles(data,"*",SearchOption.AllDirectories).Any(p=>p.Contains("user-edits")&&File.ReadAllText(p).Contains("user edit")),"modified owned config retained in backup before removal");Call(installer,"Disable");Check(!(bool)type.GetProperty("Enabled").GetValue(installer,null),"repeated disable is safe");
   Call(installer,"Enable",cache);using(var locked=new FileStream(Path.Combine(game,"ReShade.ini"),FileMode.Open,FileAccess.Read,FileShare.None)){bool failed=false;try{Call(installer,"Disable");}catch{failed=true;}Check(failed&&File.Exists(Path.Combine(game,"opengl32.dll")),"locked file stops removal before partial uninstall");}Call(installer,"Disable");
   Type cacheType=typeof(Engine).Assembly.GetType("PZ3D.ComponentCache");Check(cacheType!=null,"component preparation module exists");
   string evil=Path.Combine(root,"evil.zip");using(var z=System.IO.Compression.ZipFile.Open(evil,System.IO.Compression.ZipArchiveMode.Create)){using(var w=new StreamWriter(z.CreateEntry("../escape.fx").Open()))w.Write("unsafe");}bool blocked=false;try{cacheType.GetMethod("ExtractZip").Invoke(null,new object[]{evil,Path.Combine(root,"extracted")});}catch{blocked=true;}Check(blocked&&!File.Exists(Path.Combine(root,"escape.fx")),"component ZIP traversal blocked");
   Type steamType=typeof(Engine).Assembly.GetType("PZ3D.SteamWorkshop");Check(steamType!=null,"real Steam download module exists");var callback=steamType.GetMethod("SuccessResult");Check((bool)callback.Invoke(null,new object[]{(uint)108600,(ulong)3809306528,(uint)1,(ulong)3809306528}),"successful requested workshop callback accepted");Check(!(bool)callback.Invoke(null,new object[]{(uint)999,(ulong)3809306528,(uint)1,(ulong)3809306528})&&!(bool)callback.Invoke(null,new object[]{(uint)108600,(ulong)99,(uint)1,(ulong)3809306528})&&!(bool)callback.Invoke(null,new object[]{(uint)108600,(ulong)3809306528,(uint)15,(ulong)3809306528}),"wrong app item or error callback never marks download complete");
   Console.WriteLine("ORANGE DLSS FIXTURE PASSED: "+root);
  }
 }
}
